def _snowflake_endpoint() -> dict[str, object]:
    """Connector kwargs redirecting Snowflake to a local emulator, or ``{}``.

    Only ever populated from SNOWFLAKE_HOST/PORT/PROTOCOL. Blank means the real
    warehouse, so the cloud path is unchanged by construction — an emulator has to
    be opted into, it can never be fallen back into.
    """
    host = os.environ.get("SNOWFLAKE_HOST", "").strip()
    if not host:
        return {}
    endpoint: dict[str, object] = {"host": host}
    if port := os.environ.get("SNOWFLAKE_PORT", "").strip():
        endpoint["port"] = int(port)
    if protocol := os.environ.get("SNOWFLAKE_PROTOCOL", "").strip():
        endpoint["protocol"] = protocol
    return endpoint


